import numpy as np, math
D=[]
for A,r0,c0 in [(A10,4,6),(A20,5,7)]:
 for r in range(len(A)):
  for c in range(len(A[0])):
   if A[r][c] in (0,4): D.append((r,c,abs(r-r0),abs(c-c0),A[r][c]==4,len(A)))
len(D)

features={}
for name,fn in {
 'r*c':lambda d:d[0]*d[1], '(r+1)(c+1)':lambda d:(d[0]+1)*(d[1]+1),
 'a*b':lambda d:d[2]*d[3], 'a+b':lambda d:d[2]+d[3], 'r+c':lambda d:d[0]+d[1],
 'r-c':lambda d:d[0]-d[1], 'a-b':lambda d:d[2]-d[3], 'r^c':lambda d:d[0]^d[1], 'a^b':lambda d:d[2]^d[3],
 'a|b':lambda d:d[2]|d[3], 'a&b':lambda d:d[2]&d[3], 'r&c':lambda d:d[0]&d[1],
}.items(): features[name]=[fn(d) for d in D]
results=[]
for name, vals in features.items():
 for m in range(2,31):
  # classify by residue for each source row axis? optimize boolean mapping
  counts=np.zeros((m,2),int)
  for v,d in zip(vals,D): counts[v%m,int(d[4])]+=1
  acc=counts.max(axis=1).sum()/len(D)
  results.append((acc,name,m,counts))
sorted([(a,n,m) for a,n,m,_ in results],reverse=True)[:30]

